const routes={iheya:{id:'iheya',name:'伊平屋島',ship:'フェリーいへやⅢ',from:'運天港',to:'前泊港',fare:{adult:2580,child:1290},official:'https://www.vill.iheya.okinawa.jp/',status:{level:'ok',label:'通常運航',updated:'本日 7:15更新',notice:'本日は通常どおり運航予定です。'},times:[['11:00','12:20'],['15:00','16:20']]},izena:{id:'izena',name:'伊是名島',ship:'フェリーいぜな尚円',from:'運天港',to:'仲田港',fare:{adult:3500,child:1750},official:'https://www.vill.izena.okinawa.jp/',status:{level:'warn',label:'運航時間変更',updated:'本日 7:30更新',notice:'第2便は出航時刻を変更するデモ表示です。'},times:[['10:30','11:25'],['15:30','16:25']]}};
const state={route:null,step:0,trip:'片道',date:new Date(Date.now()+86400000).toISOString().slice(0,10),sailing:0,adult:1,child:0,name:'',tel:'',admin:'all'};
const app=document.querySelector('#app'); const yen=n=>n.toLocaleString('ja-JP')+'円';
const ferry=()=>document.querySelector('#ferrymaru').innerHTML;
function status(r){return `<span class="status ${r.status.level}">${r.status.level==='ok'?'🟢':r.status.level==='warn'?'🟡':'🔴'} ${r.status.label}</span>`}
function home(){document.body.classList.remove('admin-mode');location.hash='user';document.querySelector('.brand-label').textContent='島旅フェリー予約';app.innerHTML=`<section class="screen"><div class="hero"><span class="eyebrow">利用者向け予約サイト</span><h1>フェリーで、<br>島へ行こう。</h1><p>伊平屋島・伊是名島へのフェリーをかんたん予約</p><div class="cloud c1"></div><div class="cloud c2"></div><div class="island i-port">運天港</div><div class="island i-iheya">伊平屋島</div><div class="island i-izena">伊是名島</div><div class="ship-sail">${ferry()}</div><div class="speech">今日はどの島に行く？</div><div class="wave"></div></div><div class="content"><h2 class="section-title">今日はどの島へ行きますか？</h2><div class="route-grid">${Object.values(routes).map(r=>`<article class="route-card"><div class="art">${r.id==='iheya'?'🏝️🌺':'🌴🐚'}</div><p class="route">${r.from} ⇄ ${r.to}</p><h2>${r.name}</h2><p>${r.ship}</p><div class="row">${status(r)}<small>${r.status.updated}</small></div><p><b>次の便 ${r.times[0][0]}</b> → ${r.times[0][1]}</p><button class="primary" data-route="${r.id}">${r.name}を予約する →</button><p><a href="${r.official}" target="_blank">公式の運航情報 ↗</a></p></article>`).join('')}</div><section class="today"><div class="row"><div><small>運航イメージ</small><h2>今日のフェリー</h2></div><span class="status ok">リアルタイム風表示</span></div><div class="timeline"><b>運天港</b><div class="track" style="--ship-pos:${20+new Date().getHours()*2}%"></div><b>島の港</b></div><p class="notice">※ 船の位置は演出用の「運航イメージ」です。AIS等の実位置情報ではありません。運航状況はデモデータです。</p></section></div></section>`;bindHome()}
function bindHome(){document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>{state.route=b.dataset.route;state.step=0;booking()})}
const labels=['往復','乗船日','便','人数','乗船者','確認','決済','完了'];
function booking(){const r=routes[state.route];app.innerHTML=`<section class="screen booking-wrap"><div class="booking-head"><div><button class="secondary" data-home>← 島選択</button><h1>${r.name}への予約</h1><p>${r.from} ⇄ ${r.to} ・ ${r.ship}</p></div>${status(r)}</div><div class="stepper" aria-label="予約ステップ">${labels.map((_,i)=>`<i class="${i<=state.step?'on':''}"></i>`).join('')}</div><div class="panel"><small>STEP ${state.step+1} / ${labels.length}</small>${stepContent(r)}</div><p class="footer-note">これは操作体験用プロトタイプです。決済・予約登録・個人情報保存は行いません。</p></section>`;bindBooking(r)}
function stepContent(r){if(state.step===0)return `<h2>往路・復路を選択</h2><p>旅のプランに近いものを選んでね。</p><div class="choice-grid">${['片道','往復'].map(x=>`<button class="choice ${state.trip===x?'selected':''}" data-trip="${x}"><strong>${x==='片道'?'→ 片道':'⇄ 往復'}</strong>${x==='片道'?'島へ向かう便のみ':'帰りの便もまとめて'}</button>`).join('')}</div>${actions()}`;
if(state.step===1)return `<h2>乗船日を選択</h2><label class="field">乗船日<input type="date" id="date" value="${state.date}" min="${new Date().toISOString().slice(0,10)}"></label><div class="notice">季節や天候によりダイヤが変わる場合があります。運航状況もご確認ください。</div>${actions()}`;
if(state.step===2)return `<h2>乗る便を選択</h2><div class="sailings">${r.times.map((t,i)=>`<button class="sailing-card ${state.sailing===i?'selected':''}" data-sailing="${i}"><span class="status ok">🟢 予約可能</span><p><span class="time">${t[0]}</span> ${r.from}</p><p>↓ 約${r.id==='iheya'?'80':'55'}分</p><p><span class="time">${t[1]}</span> ${r.to}</p><b>${state.sailing===i?'✓ この便を選択中':'この便を選ぶ'}</b></button>`).join('')}</div>${actions()}`;
if(state.step===3)return `<h2>人数を選択</h2><div class="controls"><div class="counter"><div><b>大人</b><small> ${yen(r.fare.adult)}</small></div><div><button data-count="adult:-1">−</button> <b>${state.adult}</b> <button data-count="adult:1">＋</button></div></div><div class="counter"><div><b>小人</b><small> ${yen(r.fare.child)}</small></div><div><button data-count="child:-1">−</button> <b>${state.child}</b> <button data-count="child:1">＋</button></div></div><div class="row"><h3>合計</h3><div class="price">${yen(total(r))}</div></div></div>${actions()}`;
if(state.step===4)return `<h2>代表者情報</h2><label class="field">お名前<input id="name" placeholder="島旅 はなこ" value="${state.name}"></label><label class="field">電話番号（デモ）<input id="tel" inputmode="tel" placeholder="090-0000-0000" value="${state.tel}"></label><div class="notice">入力内容は保存・送信されません。</div>${actions()}`;
if(state.step===5)return `<h2>予約内容を確認</h2><div class="summary"><div><span>行き先</span><b>${r.name}</b></div><div><span>航路</span><b>${r.from} → ${r.to}</b></div><div><span>乗船日・便</span><b>${state.date} ${r.times[state.sailing][0]}</b></div><div><span>人数</span><b>大人${state.adult}名・小人${state.child}名</b></div><div><span>代表者</span><b>${state.name||'島旅 はなこ（デモ）'}</b></div><div><span>合計</span><b class="price">${yen(total(r))}</b></div></div>${actions('デモ決済へ')}`;
if(state.step===6)return `<h2>デモ決済</h2><div class="pay-demo"><small>DEMO PAYMENT</small><h3>お支払い金額 ${yen(total(r))}</h3><p>実際のカード情報は入力しません。「デモ決済を完了」で体験を続けられます。</p></div>${actions('デモ決済を完了')}`;
return `<div class="ticket"><div class="confetti">${Array.from({length:18},(_,i)=>`<span style="left:${i*6}%;animation-delay:${i%5*.12}s">${i%2?'●':'◆'}</span>`).join('')}</div>${ferry()}<h2>予約できたよ！</h2><p>QRコードを忘れずにね！</p><div class="qr" aria-label="デモQRコード"></div><div class="summary"><div><span>島</span><b>${r.name}</b></div><div><span>航路</span><b>${r.from} → ${r.to}</b></div><div><span>乗船日</span><b>${state.date} ${r.times[state.sailing][0]}</b></div><div><span>予約番号</span><b>DEMO-${r.id.toUpperCase()}-1029</b></div><div><span>乗船者</span><b>${state.name||'島旅 はなこ'} 様ほか</b></div></div><h3>この画面を乗船時にご提示ください</h3><button class="secondary" data-change>便を変更</button> <button class="secondary" data-cancel>予約をキャンセル</button></div>`}
function actions(next='次へ'){return `<div class="actions">${state.step?'<button class="secondary" data-prev>戻る</button>':'<span></span>'}<button class="primary" data-next>${next} →</button></div>`} function total(r){return state.adult*r.fare.adult+state.child*r.fare.child}
function bindBooking(r){document.querySelectorAll('[data-trip]').forEach(x=>x.onclick=()=>{state.trip=x.dataset.trip;booking()});document.querySelectorAll('[data-sailing]').forEach(x=>x.onclick=()=>{state.sailing=+x.dataset.sailing;booking()});document.querySelectorAll('[data-count]').forEach(x=>x.onclick=()=>{let[k,v]=x.dataset.count.split(':');state[k]=Math.max(k==='adult'?1:0,state[k]+ +v);booking()});document.querySelector('[data-prev]')?.addEventListener('click',()=>{state.step--;booking()});document.querySelector('[data-next]')?.addEventListener('click',()=>{state.date=document.querySelector('#date')?.value||state.date;state.name=document.querySelector('#name')?.value||state.name;state.tel=document.querySelector('#tel')?.value||state.tel;state.step++;booking()});document.querySelector('[data-change]')?.addEventListener('click',()=>{state.step=2;booking()});document.querySelector('[data-cancel]')?.addEventListener('click',()=>{alert('デモ予約をキャンセルしました（実データの変更はありません）');home()});bindGlobal()}
const adminData={all:[86,142,352480,'通常運航'],iheya:[48,81,198240,'通常運航'],izena:[38,61,154240,'時間変更']};
function admin(){document.body.classList.add('admin-mode');location.hash='admin';document.querySelector('.brand-label').textContent='職員管理システム';let d=adminData[state.admin];app.innerHTML=`<section class="screen admin"><div class="admin-identity"><span>🔒 職員専用</span><b>デモ環境・権限：管理者</b></div><div class="row"><div><small>STAFF CONSOLE</small><h1>運航・予約ダッシュボード</h1><p>両村の予約・乗船・運航情報を一元管理</p></div><button class="secondary" data-home>利用者画面を確認 ↗</button></div><div class="admin-tabs">${[['all','すべて'],['iheya','伊平屋'],['izena','伊是名']].map(x=>`<button data-tab="${x[0]}" class="${state.admin===x[0]?'on':''}">${x[1]}</button>`).join('')}</div><div class="metrics">${[['本日の予約',d[0]+'件'],['乗船予定',d[1]+'人'],['売上',yen(d[2])],['運航状況',d[3]]].map(x=>`<article class="metric"><small>${x[0]}</small><b data-number>${x[1]}</b></article>`).join('')}</div><div class="table"><h2>便別予約人数</h2><table><thead><tr><th>航路</th><th>便</th><th>予約</th><th>定員</th><th>状況</th></tr></thead><tbody><tr><td>伊平屋</td><td>11:00</td><td>42名</td><td>80名</td><td>${status(routes.iheya)}</td></tr><tr><td>伊是名</td><td>10:30</td><td>36名</td><td>80名</td><td>${status(routes.izena)}</td></tr></tbody></table></div><div class="table"><h2>最近の予約</h2><table><thead><tr><th>予約番号</th><th>行き先</th><th>乗船者</th><th>金額</th><th>操作</th></tr></thead><tbody><tr><td>DEMO-1042</td><td>伊平屋島</td><td>山城様 2名</td><td>5,160円</td><td><button class="secondary">便変更</button></td></tr><tr><td>DEMO-1041</td><td>伊是名島</td><td>田中様 3名</td><td>8,750円</td><td><button class="secondary">キャンセル</button></td></tr></tbody></table></div></section>`;document.querySelectorAll('[data-tab]').forEach(x=>x.onclick=()=>{state.admin=x.dataset.tab;admin()});bindGlobal()}
function bindGlobal(){document.querySelectorAll('[data-home]').forEach(x=>x.onclick=home);document.querySelectorAll('[data-admin]').forEach(x=>x.onclick=admin)}document.addEventListener('click',e=>{if(e.target.closest('[data-admin]'))admin();if(e.target.closest('[data-home]'))home()});window.addEventListener('hashchange',()=>{if(location.hash==='#admin'&&!document.body.classList.contains('admin-mode'))admin();if(location.hash==='#user'&&document.body.classList.contains('admin-mode'))home()});location.hash==='#admin'?admin():home();

